def recover(wal_records, initial_state=None):
    state = dict(initial_state or {})
    committed = set()
    aborted = set()

    # Analysis Pass
    for rec in wal_records:
        t = rec.get("type")
        tx = rec.get("tx_id")
        if t == "COMMIT":
            committed.add(tx)
        elif t == "ABORT":
            aborted.add(tx)

    # Redo Pass (Chronological)
    for rec in wal_records:
        if rec.get("type") == "WRITE":
            tx = rec.get("tx_id")
            if tx in committed and tx not in aborted:
                state[rec["key"]] = rec["new_val"]

    # Undo Pass (Reverse Chronological)
    for rec in reversed(wal_records):
        if rec.get("type") == "WRITE":
            tx = rec.get("tx_id")
            if tx not in committed or tx in aborted:
                key = rec["key"]
                if key in state and state[key] == rec["new_val"]:
                    if rec.get("old_val") is None:
                        state.pop(key, None)
                    else:
                        state[key] = rec["old_val"]

    return state
